1 | import { Hono } from 'hono';
2 | import { streamSSE } from 'hono/streaming';
3 | import { eventBus, type PlatformEvent } from '../../core/events/bus.js';
4 | 
5 | const KEEP_ALIVE_MS = 25_000;
6 | 
7 | /**
8 |  * Stream platform events as Server-Sent Events (ADR-006). The event name is
9 |  * the platform event type, the id is the bus id, and a reconnecting client
10 |  * that sends Last-Event-ID receives what it missed from the retained buffer.
11 |  */
12 | export type SseMessage = { event: string; data: unknown };
13 | 
14 | export function streamEvents(transform: (event: PlatformEvent) => SseMessage[]) {
15 |   return new Hono().get('/', c => streamSSE(c, async stream => {
16 |     const lastId = Number.parseInt(c.req.header('Last-Event-ID') ?? c.req.query('since') ?? '0', 10) || 0;
17 |     let open = true;
18 | 
19 |     const send = async (event: PlatformEvent): Promise<void> => {
20 |       for (const out of transform(event)) {
21 |         if (!open) return;
22 |         await stream.writeSSE({ event: out.event, data: JSON.stringify(out.data), id: String(event.id) });
23 |       }
24 |     };
25 | 
26 |     if (lastId > 0) for (const past of eventBus.recent(lastId)) await send(past);
27 |     const handler = (event: PlatformEvent): void => { void send(event); };
28 |     eventBus.onAny(handler);
29 |     const keepAlive = setInterval(() => { void stream.writeSSE({ event: 'ping', data: '{}' }); }, KEEP_ALIVE_MS);
30 | 
31 |     stream.onAbort(() => {
32 |       open = false;
33 |       eventBus.offAny(handler);
34 |       clearInterval(keepAlive);
35 |     });
36 |     while (open) await stream.sleep(1000);
37 |   }));
38 | }
39 | 
40 | export function registerSSERoutes(app: Hono): void {
41 |   app.route('/api/stream', streamEvents(event => [{ event: event.type, data: event }]));
42 | }
43 |

