1 | import fs from 'node:fs';
2 | import { eventBus } from '../events/bus.js';
3 | import { incidents, mutations, simulations, trajectory } from '../../store/index.js';
4 | import type { Scenario, Simulation } from '../../shared/schema/simulation.schema.js';
5 | import { generateSimulationId } from '../../shared/utils/id.js';
6 | import { diffScans } from '../../graph/scanner/diff.js';
7 | import { scanRepository, type ScanResult } from '../../graph/scanner/scanner.js';
8 | import { assertSafeId } from '../../sandbox/git.js';
9 | import { applyPatch, hasUncommittedChanges, headSha, sampleRepoPath } from '../../sandbox/sample-repo.js';
10 | import { runProbes, runTests } from '../../sandbox/runner.js';
11 | import { addWorktree, MAX_ACTIVE_FUTURES, removeWorktree, worktreeDiff } from '../../sandbox/worktrees.js';
12 | import { getRepoSpec } from '../epoch/spec-registry.js';
13 | import { trajectoryEngine } from '../epoch/trajectory.js';
14 | import { workflowEngine } from '../weave/workflow-engine.js';
15 | 
16 | export interface ScenarioInput {
17 |   id: string;
18 |   label: string;
19 |   description: string;
20 |   /** Optional unified diff applied to the worktree right away (tests, fallback). Bob usually writes the change instead. */
21 |   patch?: string | undefined;
22 | }
23 | 
24 | /**
25 |  * Counterfactual futures: fork the system at a mutation into
26 |  * isolated worktrees, let Bob (or a patch) change each one, then measure every
27 |  * future with the same tests, probes and scanner as real mutations. Results
28 |  * are scenarios for comparison, not predictions of production.
29 |  */
30 | export class FuturesSimulator {
31 |   fork(baseMutationId: string, hypothesis: string, inputs: ScenarioInput[]): Simulation {
32 |     if (inputs.length < 1 || inputs.length > 3) throw new Error('A simulation compares one to three futures');
33 |     const active = simulations.listSimulations({ status: 'RUNNING' });
34 |     if (active.length >= MAX_ACTIVE_FUTURES) throw new Error(`At most ${MAX_ACTIVE_FUTURES} simulations can run at once; finish or abandon one first`);
35 | 
36 |     const base = mutations.getMutation(baseMutationId);
37 |     if (!base) throw new Error(`Mutation ${baseMutationId} not found`);
38 |     const latest = mutations.getLatestMutation();
39 |     const baseSha = base.commit_sha ?? (latest?.mutation_id === baseMutationId ? headSha(sampleRepoPath()) : undefined);
40 |     if (!baseSha) throw new Error(`Mutation ${baseMutationId} has no commit to fork from`);
41 |     const baseHash = trajectory.getTrajectoryPoint(baseMutationId)?.state_hash ?? 'unknown';
42 | 
43 |     const simulationId = generateSimulationId();
44 |     const scenarios: Scenario[] = inputs.map(input => {
45 |       const scenarioId = assertSafeId(input.id, 'scenario id');
46 |       const worktree = addWorktree(simulationId, scenarioId, baseSha);
47 |       if (input.patch) applyPatch(input.patch, worktree);
48 |       return {
49 |         scenario_id: scenarioId,
50 |         label: input.label,
51 |         description: input.description,
52 |         branch_name: `epoch/sim-${scenarioId}-${simulationId}`,
53 |         worktree_path: worktree,
54 |         status: 'RUNNING',
55 |         changes: input.patch ? ['patch applied at fork time'] : []
56 |       };
57 |     });
58 | 
59 |     const simulation: Simulation = {
60 |       simulation_id: simulationId,
61 |       base_mutation_id: baseMutationId,
62 |       base_state_hash: baseHash,
63 |       hypothesis,
64 |       scenarios,
65 |       status: 'RUNNING',
66 |       created_at: Date.now()
67 |     };
68 |     simulations.insertSimulation(simulation);
69 |     eventBus.emit('simulation.started', { simulationId, baseMutationId, hypothesis, scenarios: scenarios.map(s => ({ id: s.scenario_id, label: s.label, worktree: s.worktree_path ?? null })) });
70 |     return simulation;
71 |   }
72 | 
73 |   /** Measure one future: tests, probes and a structural scan of its worktree. */
74 |   async evaluate(simulationId: string, scenarioId: string): Promise<Simulation> {
75 |     const simulation = this.require(simulationId);
76 |     const scenario = simulation.scenarios.find(s => s.scenario_id === scenarioId);
77 |     if (!scenario?.worktree_path) throw new Error(`Scenario ${scenarioId} not found in ${simulationId}`);
78 |     if (!fs.existsSync(scenario.worktree_path)) throw new Error(`Worktree for ${scenarioId} no longer exists`);
79 | 
80 |     const spec = getRepoSpec();
81 |     const baseScan = trajectory.getScanForMutation(simulation.base_mutation_id) as ScanResult | undefined;
82 |     const [tests, probes] = await Promise.all([runTests(scenario.worktree_path), runProbes(scenario.worktree_path)]);
83 |     const scan = scanRepository(scenario.worktree_path, spec, { tests, probes, previous: baseScan });
84 |     const diff = diffScans(baseScan ?? scan, scan);
85 |     const patch = worktreeDiff(scenario.worktree_path);
86 | 
87 |     const updated: Scenario = {
88 |       ...scenario,
89 |       status: 'COMPLETED',
90 |       changes: patch.split('\n').filter(l => l.startsWith('+++ b/')).map(l => l.slice(6)),
91 |       diff: patch,
92 |       invariant_outcomes: scan.invariants.map(r => ({ invariant_id: r.invariantId, status: r.status })),
93 |       tests_passed: tests.passed,
94 |       tests_failed: tests.failed,
95 |       probes_failed: probes.filter(p => !p.ok).map(p => p.id),
96 |       coupling_score_after: scan.couplingScore,
97 |       boundary_integrity_after: scan.boundaryIntegrityScore,
98 |       test_pass_rate: tests.passed + tests.failed > 0 ? Math.round((tests.passed / (tests.passed + tests.failed)) * 1000) / 1000 : 0,
99 |       trajectory_delta: {
100 |         couplingDelta: diff.couplingDelta,
101 |         boundaryIntegrityDelta: diff.boundaryIntegrityDelta,
102 |         behaviorDelta: diff.behaviorDelta,
103 |         invariantChanges: diff.invariantTransitions.map(t => ({ invariant_id: t.invariantId, previousStatus: t.from, newStatus: t.to }))
104 |       }
105 |     };
106 |     const scenarios = simulation.scenarios.map(s => (s.scenario_id === scenarioId ? updated : s));
107 |     const allDone = scenarios.every(s => s.status === 'COMPLETED' || s.status === 'FAILED');
108 |     const next: Simulation = { ...simulation, scenarios, status: allDone ? 'COMPLETED' : 'RUNNING' };
109 |     if (allDone) next.completed_at = Date.now();
110 |     simulations.updateSimulation(next);
111 | 
112 |     eventBus.emit('simulation.updated', {
113 |       simulationId,
114 |       scenarioId,
115 |       boundaryIntegrityAfter: scan.boundaryIntegrityScore,
116 |       couplingAfter: scan.couplingScore,
117 |       withinEnvelope: trajectoryEngine.isWithinEnvelope(scan.couplingScore, scan.boundaryIntegrityScore),
118 |       testsFailed: tests.failed,
119 |       probesFailed: updated.probes_failed ?? []
120 |     });
121 |     if (allDone) eventBus.emit('simulation.completed', { simulationId, recommended: this.recommend(next)?.scenario_id ?? null });
122 |     return next;
123 |   }
124 | 
125 |   async evaluateAll(simulationId: string): Promise<Simulation> {
126 |     const simulation = this.require(simulationId);
127 |     let latest = simulation;
128 |     for (const scenario of simulation.scenarios) latest = await this.evaluate(simulationId, scenario.scenario_id);
129 |     return latest;
130 |   }
131 | 
132 |   /** The future with the best measured outcome: fewest failures, then highest boundary integrity, then smallest diff. */
133 |   recommend(simulation: Simulation): Scenario | undefined {
134 |     return simulation.scenarios
135 |       .filter(s => s.status === 'COMPLETED')
136 |       .sort((a, b) =>
137 |         (a.tests_failed ?? 0) + (a.probes_failed?.length ?? 0) - ((b.tests_failed ?? 0) + (b.probes_failed?.length ?? 0)) ||
138 |         (b.boundary_integrity_after ?? 0) - (a.boundary_integrity_after ?? 0) ||
139 |         (a.changes.length - b.changes.length)
140 |       )[0];
141 |   }
142 | 
143 |   /**
144 |    * Adopt a future: its diff is applied to the sample repo and a remediation
145 |    * workflow is started for it. The change still goes through the approval gate.
146 |    */
147 |   select(simulationId: string, scenarioId: string, actor: string): { simulation: Simulation; workflowId: string } {
148 |     const simulation = this.require(simulationId);
149 |     const scenario = simulation.scenarios.find(s => s.scenario_id === scenarioId);
150 |     if (!scenario) throw new Error(`Scenario ${scenarioId} not found`);
151 |     if (scenario.status !== 'COMPLETED' || !scenario.diff) throw new Error(`Scenario ${scenarioId} has not been evaluated yet`);
152 |     const repo = sampleRepoPath();
153 |     if (hasUncommittedChanges(repo)) throw new Error('The sample repository has uncommitted changes; approve or reject the open workflow first');
154 |     if (mutations.getLatestMutation()?.mutation_id !== simulation.base_mutation_id) {
155 |       throw new Error(`The system moved past ${simulation.base_mutation_id} since this simulation was forked; fork again from the latest mutation`);
156 |     }
157 | 
158 |     applyPatch(scenario.diff, repo);
159 |     const openIncidents = incidents.listIncidents().filter(i => i.status !== 'resolved' && i.status !== 'wont_fix');
160 |     const { workflow } = workflowEngine.start({
161 |       kind: 'remediation',
162 |       title: `Adopt future ${scenario.label}`,
163 |       requirement: `${scenario.label}. ${scenario.description}`,
164 |       author: actor,
165 |       source: 'epoch-futures',
166 |       payload: { simulation_id: simulationId, scenario_id: scenarioId, incidents: openIncidents.map(i => i.incident_id) }
167 |     });
168 |     for (const incident of openIncidents) {
169 |       incidents.setRemediationWorkflow(incident.incident_id, workflow.workflow_id);
170 |       incidents.updateIncidentStatus(incident.incident_id, 'remediation_in_progress');
171 |     }
172 | 
173 |     const next: Simulation = { ...simulation, selected_scenario_id: scenarioId };
174 |     simulations.updateSimulation(next);
175 |     eventBus.emit('simulation.updated', { simulationId, selectedScenarioId: scenarioId, workflowId: workflow.workflow_id, actor });
176 |     return { simulation: next, workflowId: workflow.workflow_id };
177 |   }
178 | 
179 |   /** Remove a simulation's worktrees. */
180 |   cleanup(simulationId: string): Simulation {
181 |     const simulation = this.require(simulationId);
182 |     for (const s of simulation.scenarios) if (s.worktree_path) removeWorktree(s.worktree_path);
183 |     const next: Simulation = { ...simulation, status: simulation.selected_scenario_id ? 'COMPLETED' : 'ABANDONED' };
184 |     if (!next.completed_at) next.completed_at = Date.now();
185 |     simulations.updateSimulation(next);
186 |     return next;
187 |   }
188 | 
189 |   private require(simulationId: string): Simulation {
190 |     const simulation = simulations.getSimulation(simulationId);
191 |     if (!simulation) throw new Error(`Simulation ${simulationId} not found`);
192 |     return simulation;
193 |   }
194 | }
195 | 
196 | export const futuresSimulator = new FuturesSimulator();
