1 | /**
2 |  * One shared EventSource on GET /api/v1/stream for the whole console. Hooks
3 |  * subscribe to topics and refetch when something they show changes.
4 |  *
5 |  * The browser reconnects by itself (sending Last-Event-ID); when the stream
6 |  * fails hard (the API is down and the dev proxy answers an error), we reconnect
7 |  * with backoff. After any reconnect every subscriber refetches, because events
8 |  * may have been missed.
9 |  */
10 | 
11 | export type LiveTopic = 'activity' | 'task' | 'mutation' | 'drift' | 'invariant' | 'workflow' | 'reset';
12 | export type StreamStatus = 'connecting' | 'live' | 'reconnecting' | 'offline';
13 | 
14 | type Listener = (topic: LiveTopic, data: unknown) => void;
15 | 
16 | const STREAM_PATH = '/api/v1/stream';
17 | const EVENT_TOPICS: Record<string, LiveTopic> = {
18 |   'epoch.activity': 'activity',
19 |   'epoch.task': 'task',
20 |   'epoch.mutation': 'mutation',
21 |   'epoch.drift': 'drift',
22 |   'epoch.invariant': 'invariant',
23 |   'epoch.workflow': 'workflow'
24 | };
25 | 
26 | const listeners = new Set<Listener>();
27 | const statusListeners = new Set<() => void>();
28 | let source: EventSource | null = null;
29 | let status: StreamStatus = 'connecting';
30 | let failures = 0;
31 | let retryTimer: ReturnType<typeof setTimeout> | undefined;
32 | 
33 | function setStatus(next: StreamStatus): void {
34 |   if (status === next) return;
35 |   status = next;
36 |   for (const listener of [...statusListeners]) listener();
37 | }
38 | 
39 | function publish(topic: LiveTopic, data: unknown): void {
40 |   for (const listener of [...listeners]) listener(topic, data);
41 | }
42 | 
43 | function scheduleReconnect(): void {
44 |   if (retryTimer) return;
45 |   const delay = Math.min(15_000, 1_000 * 2 ** Math.min(failures, 4));
46 |   failures += 1;
47 |   retryTimer = setTimeout(() => {
48 |     retryTimer = undefined;
49 |     connect();
50 |   }, delay);
51 | }
52 | 
53 | /**
54 |  * The API sends the stream's headers with its first event (or the 25 s
55 |  * keep-alive), so 'open' can be late. A stream that is still connecting after
56 |  * a moment, without an error, is up: a down API fails fast through the proxy.
57 |  */
58 | const ASSUME_LIVE_MS = 2_500;
59 | 
60 | function connect(): void {
61 |   if (source || typeof EventSource === 'undefined') return;
62 |   const es = new EventSource(STREAM_PATH);
63 |   source = es;
64 |   let assume: ReturnType<typeof setTimeout> | undefined;
65 | 
66 |   /** Up (again): after a drop, every subscriber refetches what it may have missed. */
67 |   const markLive = (): void => {
68 |     clearTimeout(assume);
69 |     if (source !== es || status === 'live') return;
70 |     const recovered = status === 'reconnecting' || status === 'offline';
71 |     failures = 0;
72 |     setStatus('live');
73 |     if (recovered) publish('reset', null);
74 |   };
75 |   const assumeLiveSoon = (): void => {
76 |     clearTimeout(assume);
77 |     assume = setTimeout(() => {
78 |       if (es.readyState === EventSource.CONNECTING) markLive();
79 |     }, ASSUME_LIVE_MS);
80 |   };
81 |   assumeLiveSoon();
82 | 
83 |   es.onopen = markLive;
84 | 
85 |   es.onerror = () => {
86 |     clearTimeout(assume);
87 |     if (es.readyState === EventSource.CLOSED) {
88 |       es.close();
89 |       if (source === es) source = null;
90 |       setStatus('offline');
91 |       scheduleReconnect();
92 |     } else {
93 |       // The browser reconnects by itself (with Last-Event-ID).
94 |       setStatus('reconnecting');
95 |       assumeLiveSoon();
96 |     }
97 |   };
98 | 
99 |   for (const [name, topic] of Object.entries(EVENT_TOPICS)) {
100 |     es.addEventListener(name, event => {
101 |       markLive();
102 |       let data: unknown;
103 |       try {
104 |         data = JSON.parse((event as MessageEvent<string>).data);
105 |       } catch {
106 |         return;
107 |       }
108 |       publish(topic, data);
109 |     });
110 |   }
111 | }
112 | 
113 | /** Listen to live events; the stream opens on the first subscriber and stays open. */
114 | export function subscribeLive(listener: Listener): () => void {
115 |   listeners.add(listener);
116 |   connect();
117 |   return () => {
118 |     listeners.delete(listener);
119 |   };
120 | }
121 | 
122 | /** Ask every live hook to refetch (after a demo restore, for example). */
123 | export function refreshAll(): void {
124 |   publish('reset', null);
125 | }
126 | 
127 | export function subscribeStreamStatus(listener: () => void): () => void {
128 |   statusListeners.add(listener);
129 |   connect();
130 |   return () => {
131 |     statusListeners.delete(listener);
132 |   };
133 | }
134 | 
135 | export const getStreamStatus = (): StreamStatus => status;
