1 | import { useState, useEffect, useCallback, useRef } from 'react';
2 | import { apiGet } from '../api/client';
3 | import { subscribeLive } from '../api/live';
4 | import type { ActivityEvent } from '../types';
5 | 
6 | const MAX_EVENTS = 50;
7 | 
8 | /**
9 |  * Activity feed: GET /api/v1/activity for the backlog, then `epoch.activity`
10 |  * events from the shared /api/v1/stream connection. Pausing freezes the list;
11 |  * resuming reloads the backlog so nothing is lost.
12 |  */
13 | export function useEventStream(isStreamingActive: boolean = true) {
14 |   const [events, setEvents] = useState<ActivityEvent[]>([]);
15 |   const [isPaused, setIsPaused] = useState<boolean>(!isStreamingActive);
16 |   const [error, setError] = useState<unknown>(null);
17 |   const [isLoading, setIsLoading] = useState<boolean>(true);
18 |   const pausedRef = useRef(isPaused);
19 |   pausedRef.current = isPaused;
20 | 
21 |   const loadBacklog = useCallback(async () => {
22 |     try {
23 |       const backlog = await apiGet<ActivityEvent[]>(`/api/v1/activity?limit=${MAX_EVENTS}`);
24 |       setEvents(backlog);
25 |       setError(null);
26 |     } catch (err) {
27 |       setError(err);
28 |     } finally {
29 |       setIsLoading(false);
30 |     }
31 |   }, []);
32 | 
33 |   useEffect(() => {
34 |     void loadBacklog();
35 |   }, [loadBacklog]);
36 | 
37 |   useEffect(() => {
38 |     return subscribeLive((topic, data) => {
39 |       if (topic === 'reset') {
40 |         if (!pausedRef.current) void loadBacklog();
41 |         return;
42 |       }
43 |       if (topic !== 'activity' || pausedRef.current) return;
44 |       const event = data as ActivityEvent;
45 |       setEvents(prev => (prev.some(e => e.id === event.id) ? prev : [event, ...prev].slice(0, MAX_EVENTS)));
46 |     });
47 |   }, [loadBacklog]);
48 | 
49 |   const setPaused = useCallback((paused: boolean) => {
50 |     setIsPaused(paused);
51 |     if (!paused) void loadBacklog();
52 |   }, [loadBacklog]);
53 | 
54 |   const clearEvents = useCallback(() => {
55 |     setEvents([]);
56 |   }, []);
57 | 
58 |   return {
59 |     events,
60 |     isPaused,
61 |     setIsPaused: setPaused,
62 |     clearEvents,
63 |     isLoading,
64 |     error
65 |   };
66 | }
