1 | import { useState, useMemo, useCallback } from 'react';
2 | import { useApi } from './useApi';
3 | import { apiPost, describeError } from '../api/client';
4 | import type { CounterfactualScenario, Mutation, Workflow } from '../types';
5 | 
6 | /**
7 |  * Futures lens: the measured futures from GET /api/v1/simulations. Adopting one
8 |  * (POST /api/v1/simulations/remediate) applies its diff and opens a remediation
9 |  * workflow, which the Current lens then shows.
10 |  */
11 | export function useSimulations(requestedMutationId?: string | null) {
12 |   const simsRes = useApi<CounterfactualScenario[]>('/api/v1/simulations', ['workflow', 'mutation']);
13 |   const all = useMemo(() => simsRes.data ?? [], [simsRes.data]);
14 | 
15 |   const divergenceIds = useMemo(() => [...new Set(all.map(s => s.divergenceMutationId))], [all]);
16 |   const [divergenceState, setDivergenceMutationId] = useState<string | null>(requestedMutationId ?? null);
17 | 
18 |   /** A requested branch point without futures falls back to the newest one that has some. */
19 |   const requestedMissing = divergenceState !== null && all.length > 0 && !divergenceIds.includes(divergenceState);
20 |   const divergenceMutationId = divergenceState && divergenceIds.includes(divergenceState)
21 |     ? divergenceState
22 |     : divergenceIds.at(-1) ?? null;
23 | 
24 |   const scenarios = useMemo(() => {
25 |     const forPoint = all.filter(s => s.divergenceMutationId === divergenceMutationId);
26 |     // Several forks from one mutation: show the newest simulation's futures.
27 |     const simulationIds = [...new Set(forPoint.map(s => s.simulationId ?? s.id.split(':')[0]))];
28 |     const newest = simulationIds.at(-1);
29 |     return forPoint.filter(s => (s.simulationId ?? s.id.split(':')[0]) === newest);
30 |   }, [all, divergenceMutationId]);
31 | 
32 |   const divergenceRes = useApi<Mutation>(divergenceMutationId ? `/api/v1/mutations/${divergenceMutationId}` : null);
33 | 
34 |   const [selectedScenarioState, setSelectedScenarioId] = useState<string | null>(null);
35 |   const recommended = scenarios.find(s => s.recommended);
36 |   const selectedScenarioId = selectedScenarioState && scenarios.some(s => s.id === selectedScenarioState)
37 |     ? selectedScenarioState
38 |     : (recommended ?? scenarios[0])?.id ?? '';
39 |   const activeScenario = scenarios.find(s => s.id === selectedScenarioId) ?? null;
40 |   const adoptedScenario = scenarios.find(s => s.selected) ?? null;
41 | 
42 |   const [isDecisionModalOpen, setIsDecisionModalOpen] = useState<boolean>(false);
43 |   const [isAdopting, setIsAdopting] = useState<boolean>(false);
44 |   const [adoptError, setAdoptError] = useState<string | null>(null);
45 | 
46 |   /** Adopt a measured future. Resolves to the remediation workflow id, or null when the API refused. */
47 |   const adopt = useCallback(async (scenarioId: string): Promise<string | null> => {
48 |     setIsAdopting(true);
49 |     setAdoptError(null);
50 |     try {
51 |       const result = await apiPost<{ workflowId: string; workflow: Workflow }>('/api/v1/simulations/remediate', { scenarioId });
52 |       setIsDecisionModalOpen(false);
53 |       void simsRes.reload();
54 |       return result.workflowId;
55 |     } catch (error) {
56 |       setAdoptError(describeError(error, 'write'));
57 |       return null;
58 |     } finally {
59 |       setIsAdopting(false);
60 |     }
61 |   }, [simsRes]);
62 | 
63 |   return {
64 |     isLoading: simsRes.isLoading && simsRes.data === undefined,
65 |     error: simsRes.data === undefined ? simsRes.error : null,
66 |     reload: simsRes.reload,
67 |     scenarios,
68 |     divergenceIds,
69 |     divergenceMutationId,
70 |     setDivergenceMutationId,
71 |     requestedMutationId: divergenceState,
72 |     requestedMissing,
73 |     divergenceMutation: divergenceRes.data ?? null,
74 |     selectedScenarioId,
75 |     setSelectedScenarioId,
76 |     activeScenario,
77 |     adoptedScenario,
78 |     adopt,
79 |     isAdopting,
80 |     adoptError,
81 |     setAdoptError,
82 |     isDecisionModalOpen,
83 |     setIsDecisionModalOpen
84 |   };
85 | }
