11 | export function isolate(label: string): { dir: string; cleanup: () => void } {
12 |   const dir = fs.mkdtempSync(path.join(os.tmpdir(), `epoch-${label}-`));
13 |   process.env.EPOCH_WORK_DIR = path.join(dir, 'work');
14 |   delete process.env.EPOCH_SAMPLE_REPO;
15 |   setDbPath(path.join(dir, 'epoch.db'));
16 |   clearRepoSpecCache();
17 |   return {
18 |     dir,
19 |     cleanup: () => {
20 |       closeDb();
21 |       try {
22 |         fs.rmSync(dir, { recursive: true, force: true, maxRetries: 5, retryDelay: 200 });
23 |       } catch {
24 |         // Windows can hold git or SQLite handles briefly; a leftover temp dir is harmless.
25 |       }
26 |     }
27 |   };
28 | }
